-- Generated by scripts/patents/sql.ts from src/patents/technologies.ts.
-- Do not edit by hand: change the technologies and run
--   bun scripts/patents/fetch.ts --write-queries
WITH pubs AS (
    SELECT
        p.family_id,
        p.publication_number,
        p.publication_date,
        p.priority_date,
        (SELECT ANY_VALUE(t.text) FROM UNNEST(p.title_localized) AS t WHERE t.language = 'en') AS title,
        LOWER(CONCAT(
            IFNULL((SELECT ANY_VALUE(t.text) FROM UNNEST(p.title_localized) AS t WHERE t.language = 'en'), ''),
            ' ',
            IFNULL((SELECT ANY_VALUE(a.text) FROM UNNEST(p.abstract_localized) AS a WHERE a.language = 'en'), '')
        )) AS text_en,
        IF(
            ARRAY_LENGTH(p.assignee_harmonized) > 0,
            STRUCT(p.assignee_harmonized[OFFSET(0)].name AS name, p.assignee_harmonized[OFFSET(0)].country_code AS country),
            NULL
        ) AS first_assignee,
        ARRAY(SELECT c.code FROM UNNEST(p.cpc) AS c) AS codes
    FROM `patents-public-data.patents.publications` AS p
    WHERE p.priority_date >= 20100101
        AND p.family_id != '-1'
        AND EXISTS (
            SELECT 1 FROM UNNEST(p.cpc) AS c WHERE
            c.code LIKE 'B25J9/102%'
            OR c.code LIKE 'B25J9/12%'
            OR c.code LIKE 'B25J17/0241%'
            OR c.code LIKE 'H02K7/116%'
            OR c.code LIKE 'F16H49/001%'
            OR c.code LIKE 'F16H1/32%'
            OR c.code LIKE 'F16H2001/32%'
            OR c.code LIKE 'F16H1/28%'
            OR c.code LIKE 'F16H1/46%'
            OR c.code LIKE 'F16H25/22%'
            OR c.code LIKE 'H01F1/057%'
            OR c.code LIKE 'H01F41/0293%'
            OR c.code LIKE 'C22C38/005%'
            OR c.code = 'H01F1/10'
            OR c.code LIKE 'H01F1/11%'
            OR c.code = 'H01F1/047'
            OR c.code LIKE 'H02K19/103%'
            OR c.code LIKE 'H02K1/246%'
            OR c.code LIKE 'H02K21/24%'
            OR c.code LIKE 'F03G7/06%'
            OR c.code LIKE 'H10N30/20%'
            OR c.code LIKE 'B25J9/142%'
            OR c.code LIKE 'F15B15/18%'
        )
),
families AS (
    SELECT
        family_id,
        MIN(priority_date) AS priority_date,
        ARRAY_AGG(publication_number ORDER BY publication_date LIMIT 1)[OFFSET(0)] AS publication,
        ARRAY_AGG(title IGNORE NULLS ORDER BY publication_date LIMIT 1)[SAFE_OFFSET(0)] AS title,
        ARRAY_AGG(first_assignee IGNORE NULLS ORDER BY publication_date LIMIT 1)[SAFE_OFFSET(0)] AS applicant,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'B25J9/102%')) AS t0_c0,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'B25J9/12%')) AS t0_c1,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'B25J17/0241%')) AS t0_c2,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'H02K7/116%')) AS t0_c3,
        LOGICAL_OR(REGEXP_CONTAINS(text_en, r'\b(?:robot|robotic|manipulator|humanoid|exoskeleton|legged|joint actuator|rotary actuator|linear actuator)')) AS t0_c3_kw,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'F16H49/001%')) AS t1_c0,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'F16H1/32%')) AS t2_c0,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'F16H2001/32%')) AS t2_c1,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'F16H1/28%')) AS t3_c0,
        LOGICAL_OR(REGEXP_CONTAINS(text_en, r'\b(?:robot|robotic|manipulator|humanoid|exoskeleton|legged|joint actuator|rotary actuator|linear actuator)')) AS t3_c0_kw,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'F16H1/46%')) AS t3_c1,
        LOGICAL_OR(REGEXP_CONTAINS(text_en, r'\b(?:robot|robotic|manipulator|humanoid|exoskeleton|legged|joint actuator|rotary actuator|linear actuator)')) AS t3_c1_kw,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'F16H25/22%')) AS t4_c0,
        LOGICAL_OR(REGEXP_CONTAINS(text_en, r'\b(?:robot|robotic|manipulator|humanoid|exoskeleton|legged|joint actuator|rotary actuator|linear actuator)')) AS t4_c0_kw,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'H01F1/057%')) AS t5_c0,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'H01F41/0293%')) AS t5_c1,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'C22C38/005%')) AS t5_c2,
        LOGICAL_OR(REGEXP_CONTAINS(text_en, r'\b(?:magnet)')) AS t5_c2_kw,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code = 'H01F1/10')) AS t6_c0,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'H01F1/11%')) AS t6_c1,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code = 'H01F1/047')) AS t6_c2,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'H02K19/103%')) AS t7_c0,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'H02K1/246%')) AS t7_c1,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'H02K21/24%')) AS t7_c2,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'F03G7/06%')) AS t8_c0,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'H10N30/20%')) AS t8_c1,
        LOGICAL_OR(REGEXP_CONTAINS(text_en, r'\b(?:artificial muscle|dielectric elastomer|hasel|electrohydraulic|soft actuator)')) AS t8_c1_kw,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'B25J9/142%')) AS t8_c2,
        LOGICAL_OR(REGEXP_CONTAINS(text_en, r'\b(?:artificial muscle|dielectric elastomer|hasel|electrohydraulic|soft actuator)')) AS t8_c2_kw,
        LOGICAL_OR(EXISTS(SELECT 1 FROM UNNEST(codes) AS code WHERE code LIKE 'F15B15/18%')) AS t8_c3,
        LOGICAL_OR(REGEXP_CONTAINS(text_en, r'\b(?:robot|robotic|manipulator|humanoid|exoskeleton|legged|joint actuator|rotary actuator|linear actuator)')) AS t8_c3_kw
    FROM pubs
    GROUP BY family_id
)
SELECT
    family_id,
    priority_date,
    publication,
    title,
    applicant.name AS assignee,
    applicant.country AS country,
    ARRAY_TO_STRING(
        ARRAY(SELECT x FROM UNNEST([
            IF(t0_c0 OR t0_c1 OR t0_c2 OR (t0_c3 AND t0_c3_kw), 'robot-joints', NULL),
            IF(t1_c0, 'strain-wave', NULL),
            IF(t2_c0 OR t2_c1, 'cycloidal', NULL),
            IF((t3_c0 AND t3_c0_kw) OR (t3_c1 AND t3_c1_kw), 'planetary', NULL),
            IF((t4_c0 AND t4_c0_kw), 'screws', NULL),
            IF(t5_c0 OR t5_c1 OR (t5_c2 AND t5_c2_kw), 'ndfeb', NULL),
            IF(t6_c0 OR t6_c1 OR t6_c2, 'ree-free-magnets', NULL),
            IF(t7_c0 OR t7_c1 OR t7_c2, 'ree-free-motors', NULL),
            IF(t8_c0 OR (t8_c1 AND t8_c1_kw) OR (t8_c2 AND t8_c2_kw) OR (t8_c3 AND t8_c3_kw), 'artificial-muscles', NULL)
        ]) AS x WHERE x IS NOT NULL),
        ','
    ) AS technologies
FROM families
WHERE (t0_c0 OR t0_c1 OR t0_c2 OR (t0_c3 AND t0_c3_kw))
    OR (t1_c0)
    OR (t2_c0 OR t2_c1)
    OR ((t3_c0 AND t3_c0_kw) OR (t3_c1 AND t3_c1_kw))
    OR ((t4_c0 AND t4_c0_kw))
    OR (t5_c0 OR t5_c1 OR (t5_c2 AND t5_c2_kw))
    OR (t6_c0 OR t6_c1 OR t6_c2)
    OR (t7_c0 OR t7_c1 OR t7_c2)
    OR (t8_c0 OR (t8_c1 AND t8_c1_kw) OR (t8_c2 AND t8_c2_kw) OR (t8_c3 AND t8_c3_kw))
ORDER BY family_id
